// A Node-RED function node runs in a sandbox that has no `process`: reading
// process.env here threw an uncaught ReferenceError that took the whole
// runtime down, and it only threw where no ingress announced the prefix --
// so the dev stack died on its first status-list request while CI, behind a
// prefix-stripping Traefik, never reached the expression at all. `env.get`
// is the sandbox's own reader, and it is read once here rather than inside
// the closure, which other nodes call from their own sandboxes.
var configuredPrefix = env.get('ISSUER_PATH_PREFIX') || '';

global.set('getBaseUrl', function (msg) {
    var req = (msg && msg.req) || {};
    var headers = req.headers || {};
    var host = headers['x-forwarded-host'] || headers.host || 'localhost:1880';
    var isLocal = /^(localhost|127\.0\.0\.1)(:\d+)?$/.test(host);
    var proto = headers['x-forwarded-proto'] || (isLocal ? 'http' : 'https');
    // Deployments behind a path prefix (ingress route such as /issuer that is
    // stripped before reaching Node-RED) must still advertise the prefix in every
    // URL they hand out, or the wallet fetches paths the ingress does not route
    // here. The ingress supplies it as X-Forwarded-Prefix; ISSUER_PATH_PREFIX is
    // the fallback for proxies that do not.
    var prefix = headers['x-forwarded-prefix'] || configuredPrefix;
    prefix = String(prefix).replace(/\/+$/, '');
    if (prefix && prefix[0] !== '/') prefix = '/' + prefix;
    return proto + '://' + host + prefix;
});

// Persistent (survives pod restarts, unlike Node-RED's default in-memory
// global context store) status-list bitstring + issued-credential registry,
// so revocations made via /admin stick and the admin page can list every
// credential ever issued. Lives on the PVC under /data/status.
var STATUS_DIR = '/data/status';
var BITS_PATH = STATUS_DIR + '/bits.bin';
var REGISTRY_PATH = STATUS_DIR + '/registry.json';
var DEFAULT_BITS_LEN = 1250; // 10000 one-bit slots

function ensureDir() {
    fs.mkdirSync(STATUS_DIR, { recursive: true });
}

global.set('loadStatusBits', function (minBytes) {
    ensureDir();
    var bits = fs.existsSync(BITS_PATH) ? fs.readFileSync(BITS_PATH) : Buffer.alloc(DEFAULT_BITS_LEN, 0);
    if (minBytes && bits.length < minBytes) {
        var grown = Buffer.alloc(Math.max(minBytes, bits.length * 2), 0);
        bits.copy(grown);
        bits = grown;
    }
    return bits;
});

global.set('saveStatusBits', function (bits) {
    ensureDir();
    fs.writeFileSync(BITS_PATH, bits);
});

// Bit ordering: LSB-first within each byte -- confirmed against DCS's own
// reader (backend/internal/auth/oid4vp/status/codec/bitreader.go,
// ReadStatusValue called with codec.LSBFirst in handler/ietf_token.go: bit i
// is (byte[i>>3] >> (i%8)) & 1). Getting this backwards is a silent
// correctness bug -- a self-consistent set+get round-trip (this system
// reading its own bits back) passes either way, but a real external
// verifier using the opposite convention reads a DIFFERENT bit than the one
// that was actually flipped, so revocation would appear to work here while
// doing nothing from DCS's point of view.
global.set('getStatusBit', function (bits, idx) {
    var byteIdx = idx >> 3, bitIdx = idx % 8;
    if (byteIdx >= bits.length) return false;
    return ((bits[byteIdx] >> bitIdx) & 1) === 1;
});
global.set('setStatusBit', function (bits, idx, value) {
    var byteIdx = idx >> 3, bitIdx = idx % 8;
    if (value) bits[byteIdx] |= (1 << bitIdx);
    else bits[byteIdx] &= ~(1 << bitIdx);
});

global.set('loadRegistry', function () {
    ensureDir();
    if (!fs.existsSync(REGISTRY_PATH)) return [];
    try {
        return JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
    } catch (e) {
        return [];
    }
});

global.set('saveRegistry', function (list) {
    ensureDir();
    fs.writeFileSync(REGISTRY_PATH, JSON.stringify(list, null, 2));
});

// This container's system clock can be far ahead of real-world time (see
// the PKI tab's faketime comment). Stamping issued-at times from it makes
// credentials display an obviously-wrong date. The container's clock can't
// be trusted, but any external HTTPS server's response carries an accurate
// `Date` header -- use that as a free, reliable real-world time source
// instead of running our own NTP client. Falls back to null on any failure
// (offline pod, DNS hiccup) so callers can use their own safe default.
global.set('getRealWorldNowSeconds', function () {
    return new Promise((resolve) => {
        const req = https.request('https://cloudflare.com', { method: 'HEAD', timeout: 3000 }, (res) => {
            const d = res.headers.date;
            res.resume();
            resolve(d ? Math.floor(new Date(d).getTime() / 1000) : null);
        });
        req.on('timeout', () => { req.destroy(); resolve(null); });
        req.on('error', () => resolve(null));
        req.end();
    });
});

node.log('global helpers installed (getBaseUrl, status bits, registry, getRealWorldNowSeconds)');
return null;
